-- Study Abroad country content, BATCH 9: Russia, Georgia, Kazakhstan, Philippines, South Africa.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('russia', 'georgia', 'kazakhstan', 'philippines', 'south-africa'));
UPDATE countries SET why_title = 'Why study in Russia?', why_body = '<p>Russia has a long tradition in science, engineering and medicine, with low tuition and government-funded places for international students. Lomonosov Moscow State University is reported at joint 115th in the QS World University Rankings 2027.</p><ul><li>Low tuition and living costs compared with most Western countries</li><li>Government scholarships and quota places for international students</li><li>Strong in medicine, engineering, physics, mathematics and computing</li><li>English-taught programmes at selected universities</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students need a <strong>student visa</strong>, usually issued after the university sends an official invitation and admission confirmation. Check travel advisories and payment options for your country before you apply.</p><ul><li>Admission letter or invitation from a Russian university</li><li>Passport, photographs, medical certificate (including an HIV test) and academic records</li><li>Apply well ahead: guides advise at least 3 months before travel, with processing reported at 10-20 working days</li><li>After arrival: contact the university international office, register your stay and complete migration formalities</li><li>Check current rules on banking, payments and travel before committing to a place</li><li>Work: student visa holders have limited work rights, so check with the university</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Russian embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university or through the national government scholarship process (Open Doors and quota places).</p><ul><li>Academic transcripts and certificates, legalised or apostilled</li><li>Language proof (Russian or English)</li><li>Motivation letter and CV for Master''s programmes</li><li>Entrance exams or interviews for some programmes (medicine and engineering often have tests)</li><li>Passport copy and photographs</li><li>Government scholarship applications go through the Education in Russia portal or your national quota office</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition is lower than in most Western countries. Government-funded places can cover tuition and give a stipend.</p><ul><li>Tuition (self-funded): roughly US$2,500-$7,000 a year for many programmes (estimate; medicine and some programmes are higher)</li><li>Living costs: about US$300-$800 a month; Moscow and St Petersburg are more expensive</li><li>Government scholarship: tuition free with a small stipend and dormitory for eligible students</li><li>Health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results; many universities require a preparatory Russian-language year for Russian-taught programmes</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Russian (TORFL level B1-B2) for Russian-taught courses; English proof for English-taught courses</li><li>Scholarship applicants must be from eligible countries and meet age limits</li></ul>' WHERE slug = 'russia';
UPDATE countries SET why_title = 'Why study in Georgia?', why_body = '<p>Georgia offers low-cost degrees, English-taught programmes and a welcoming environment in the Caucasus. It is especially popular for medicine, with many international students enrolled in medical programmes at private universities.</p><ul><li>English-taught medicine, dentistry and business programmes</li><li>Lower tuition and living costs than most European countries</li><li>Easy entry and a safe, friendly environment</li><li>Growing number of international students</li></ul>', visa_title = 'Student visa and residence permit', visa_body = '<p>International students need a <strong>D3 study visa</strong> and then a <strong>student residence permit (TRC)</strong>, applied for through the Public Service Hall once enrolled.</p><ul><li>Enrolment certificate from an accredited Georgian institution</li><li>Passport, application form and photographs</li><li>D3 study visa first: converting a tourist status to a student permit can be more difficult</li><li>Apply for the residence permit at least 40 days before the legal stay ends</li><li>New rules reported for 2026 (unconfirmed): extra admission requirements such as a language certificate, and permit cancellation for academic failure</li><li>Check the final adopted rules with the university and the Public Service Hall</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Public Service Hall and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Some require entrance tests or a language exam.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English or Georgian language proof</li><li>Entrance exam or interview for some programmes (for example medicine)</li><li>Motivation letter for Master''s programmes</li><li>Passport copy and photographs</li><li>Medical report for some programmes</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and programme. Medicine costs more than other fields.</p><ul><li>Tuition: roughly US$2,500-$6,000 a year for most programmes, and US$6,000-$10,000 for medicine (estimates; check each university)</li><li>Living costs: about US$300-$600 a month; Tbilisi is more expensive</li><li>Residence permit costs: modest government fees</li><li>Health insurance is recommended</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or university English test for English-taught courses</li><li>Medicine usually has an entrance test or interview</li></ul>' WHERE slug = 'georgia';
UPDATE countries SET why_title = 'Why study in Kazakhstan?', why_body = '<p>Kazakhstan has the largest economy in Central Asia and offers English-taught degrees at universities such as Nazarbayev University, with low tuition and growing links to Europe and Asia.</p><ul><li>English-taught programmes at leading universities</li><li>Lower tuition and living costs than most regional destinations</li><li>Strong in engineering, energy, mining and IT</li><li>Growing scholarship opportunities</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Students from countries without visa-free entry need a <strong>C9 student visa</strong>, applied for after receiving an admission letter from the university.</p><ul><li>Acceptance letter from a Kazakhstani university</li><li>Visa application form at the embassy, with evidence of funds for tuition and living costs</li><li>Application fee: reported at about US$75</li><li>Medical certificate where required</li><li>Work: student visa holders are generally not allowed to work during their studies</li><li>Applicants who need a visa before arrival have earlier deadlines (Nazarbayev University 2026: 1 June, against 24 July for visa-on-arrival applicants)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Kazakhstan embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Nazarbayev University has an international application portal with its own deadlines.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English or Russian language proof</li><li>Motivation letter and references for Master''s programmes</li><li>Entrance tests or interviews for some programmes</li><li>Passport copy and photographs</li><li>Medical certificate where requested</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and programme. Regional universities charge less than leading universities.</p><ul><li>Tuition: roughly US$1,500-$6,000 a year for many programmes (reported guide; regional universities start from about KZT 650,000)</li><li>Foundation or preparatory years can cost more at some universities</li><li>Living costs: about US$300-$700 a month; Almaty and Astana are more expensive</li><li>Fees may rise from September 2026 (reported)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results; some universities require a foundation year</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes; Russian or Kazakh for local-language programmes</li><li>Competitive programmes use entrance tests and interviews</li></ul>' WHERE slug = 'kazakhstan';
UPDATE countries SET why_title = 'Why study in the Philippines?', why_body = '<p>The Philippines offers English-medium education at lower costs than most Western countries. It is popular for medicine and nursing programmes, business, hospitality and IT.</p><ul><li>English is the language of instruction</li><li>Lower tuition and living costs than many destinations</li><li>Strong in medicine, nursing, business and IT</li><li>Friendly, English-speaking environment</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Many students enter on a temporary visitor visa and convert to a <strong>9(f) student visa</strong> after arrival. All 9(f) holders must get an <strong>ACR I-Card</strong> from the Bureau of Immigration (BI).</p><ul><li>Admission letter and approval of the school to accept foreign students</li><li>Passport, photographs and school documents</li><li>Conversion to a 9(f) visa: reported at about PHP 9,720 in government fees, plus the ACR I-Card at about US$50</li><li>Extension of the student visa: about PHP 4,020; Special Study Permit: about PHP 5,240 (reported)</li><li>The 9(f) visa does not allow work; employment needs a separate work visa</li><li>CHED oversees school approvals; the Bureau of Immigration handles the student visa</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Bureau of Immigration (immigration.gov.ph) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Some programmes, such as medicine, require entrance tests.</p><ul><li>Academic transcripts and certificates, authenticated</li><li>English proficiency proof for some programmes</li><li>NMAT or university entrance test for medicine</li><li>Statement of purpose and references for graduate courses</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Each university sets its own tuition. Costs are lower than in most Western countries, but medical programmes cost more.</p><ul><li>Tuition: roughly US$1,500-$4,000 a year for many Bachelor''s programmes, and more for medicine (estimates)</li><li>Living costs: about US$300-$600 a month, with Manila and Cebu more expensive</li><li>Visa fees: about PHP 9,720 plus the ACR I-Card (reported)</li><li>Health insurance is recommended</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results; medicine uses a pre-medical degree and NMAT</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> usually IELTS 5.5-6.5 or a school English test for non-native speakers</li><li>Foreign students must be accepted by a school approved to enrol international students</li></ul>' WHERE slug = 'philippines';
UPDATE countries SET why_title = 'Why study in South Africa?', why_body = '<p>South Africa offers English-taught degrees at some of Africa''s best universities. The University of Cape Town is ranked 184th in the QS World University Rankings 2027, the highest in Africa.</p><ul><li>English-medium teaching and research-led universities</li><li>Strong in medicine, engineering, business, law and environmental science</li><li>Lower costs than many Western countries</li><li>Diverse culture and national parks</li></ul>', visa_title = 'Study visa requirements', visa_body = '<p>International students need a <strong>study visa</strong> from the South African embassy or consulate in their home country, applied for only after acceptance. You cannot apply after entering on a different visa.</p><ul><li>Acceptance letter from a registered South African institution</li><li>Proof of funds for tuition and living costs (figures vary: sources report from about ZAR 30,000 to ZAR 120,000, so check your embassy)</li><li>Medical cover from a scheme registered in South Africa</li><li>Police clearance and medical certificates</li><li>Passport, photographs and a return ticket or deposit</li><li>Visa fees differ by embassy; check the official schedule</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official South African embassy (DIRCO) and the Department of Home Affairs site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, with international application deadlines usually earlier than for local students.</p><ul><li>Academic transcripts and certificates, certified</li><li>SAQA evaluation of foreign qualifications where required</li><li>English language proof</li><li>Statement of purpose and references for postgraduate courses</li><li>Entrance tests (for example NBT or university tests) for some programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition for international students depends on the university and programme. Medicine and business programmes cost more.</p><ul><li>Tuition: roughly ZAR 70,000-200,000 a year for many programmes (estimate; check each university)</li><li>Living costs: about ZAR 8,000-15,000 a month; Cape Town and Johannesburg are more expensive</li><li>Medical cover is compulsory</li><li>Visa fees and a repatriation deposit may apply</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects and grades, verified by SAQA or Universities South Africa</li><li><strong>Master''s:</strong> a relevant bachelor''s degree or honours degree</li><li><strong>English:</strong> IELTS 6.0-6.5 for most programmes, or a school English test</li><li>Some programmes (medicine, law) are very competitive</li></ul>' WHERE slug = 'south-africa';
COMMIT;
